<?php
require __DIR__.'/app/public.php';$id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT)?:0;
$m=safe_public_data(function()use($id){$record=row('SELECT competition_id FROM cup_matches WHERE id=?',[$id]);if(!$record)return null;foreach(match_list(null,(int)$record['competition_id']) as $match)if((int)$match['id']===$id && $match['published'])return $match;return null;},null);
if(!$m)http_response_code(404);$pageTitle=$m?$m['home'].' vs '.$m['away'].' · Smoky Mountain Cup':'Match not found';require __DIR__.'/php/secction/header.php';
?><main id="main-content" class="cup-section"><?php if(!$m):?><h1>Match not found</h1><a href="tournament.php">Return to tournament</a><?php else:?>
<p class="cup-eyebrow"><?=h($m['season'])?> · <?=h($m['category'])?></p><h1><?=h($m['home'])?> vs <?=h($m['away'])?></h1><div data-match-detail="<?=$id?>"><?php match_card($m);?></div><p id="cup-match-penalties"><?=$m['home_penalties']!==null?'Penalties: '.h($m['home_penalties']).' – '.h($m['away_penalties']):''?></p><p class="cup-muted"><?=h($m['venue']??'Venue TBA')?> · Times shown in <?=h($m['timezone'])?>. <?=$m['confirmed']?'Official result.':'Result subject to confirmation.'?></p><h2>Match events</h2><ol id="cup-match-events"><?php foreach(safe_public_data(fn()=>rows('SELECT e.minute,e.kind,p.name AS player,t.name AS team FROM cup_events e JOIN cup_entries en ON en.id=e.entry_id JOIN cup_teams t ON t.id=en.team_id LEFT JOIN cup_rosters r ON r.id=e.roster_id LEFT JOIN cup_players p ON p.id=r.player_id WHERE e.match_id=? AND e.voided=0 ORDER BY e.minute,e.id',[$id])) as $e):?><li><?=$e['minute']?>′ · <?=h($e['team'])?> · <?=h($e['player']??'Scorer not recorded')?><?=$e['kind']==='own_goal'?' (own goal)':''?></li><?php endforeach;?></ol><a href="tournament.php?season=<?=$m['season_id']?>&category=<?=$m['competition_id']?>">Competition standings ↗</a>
<?php endif;?></main><?php require __DIR__.'/php/secction/footer.php';?>
